    text = (f"---\ntitle: \"{title}\"\nsummary: \"{summary}\"\n"
            f"season: {season}\nepisode: {number}\nstatus: {status}\n---\n\n"
            f"{summary}\n\n")
    if published:
        text += body.strip("\n") + "\n"
    if blocks:
        text = text.rstrip("\n") + "\n\n" + "\n\n".join(blocks)
    open(path, "w", encoding="utf-8").write(text.rstrip("\n") + "\n")
    print(f"{episode}: branch={len(rows)} published={len(published)} added={len(blocks)}")


